export const generateSidebarItemId = (
  server: FederationServerId,
  type: 'project' | 'buildType' | 'template' | 'title' | 'server' | 'link' | 'action',
  id?: ProjectId | BuildTypeId | TitleId | CustomSidebarItemId | FederationServerId,
): SidebarItemId => `${stringifyId(server)}_${type}_${stringifyId(id)}`
export const getOverviewExpandState = (state: State): KeyValue<ProjectId, ExpandState> => {
  const {endpoint} = getExtensionEndpoint(state, 'expandState') ?? {}
  return (
    (endpoint != null && restApi.endpoints.getExpandState.select(endpoint)(state).data) ||
    getEmptyHash()
  )
}
export const getAllProjectsExpandState = (state: State): KeyValue<ProjectId, ExpandState> =>
  state.allProjectsExpandState

export const getSearchProjectsExpandState: (
  arg0: State,
) => KeyValue<ProjectId, ExpandState> | null | undefined = state => state.searchProjectsExpandState

export const getHasFavoriteProjects: (arg0: State) => boolean | null | undefined = state =>
  getOverviewData(state).length > 0

export const getProjectsData: (
  state: State,
  rootProjectId?: ProjectId,
) => ReadonlyArray<ProjectId> = (state, rootProjectId = ROOT_PROJECT_ID) => {
  const dataWithArchived = state.projectsWithArchived[rootProjectId]?.data ?? emptyArray
  if (dataWithArchived.length > 0) {
    return dataWithArchived
  }
  const {data} = getProjectsState(state, rootProjectId)
  return data.length > 0 ? data : getProjectsState(state, ROOT_PROJECT_ID).data
}
