  createSelector(
    (state: State) => getOverviewReady(state),
    getOverviewData,
    getOverviewBuildTypesHash,
    getOverviewPipelinesHash,
    getOverviewProjectsHash,
    () => undefined,
    createDefaultOverviewTree,
  )
const getOverviewTree: (arg0: State) => ProjectsTree = createSelector(
  getDefaultOverviewTree,
  getOverviewExpandState,
  (defaultTree, expandState) =>
    upgradeTreeByExpandState({
      defaultTree,
      expandState,
      baseLevel: 0,
    }),
)
