const prepareAllProjectAndBuildTypesToConvert: (
  arg0: State,
  parentId?: ProjectId,
) => {
  ready: boolean
  data: any
  buildTypes: any
  pipelines: any
  projects: any
} = createSelector(
  getProjectsReady,
  getProjectsData,
  getBuildTypesHash,
  getPipelinesHash,
  getProjectsHash,
  (state: State) => state.projectsSidebar.showArchivedProjects,
  (ready, data, buildTypes, pipelines, projects, showArchivedProjects) => ({
    ready,
    data: showArchivedProjects ? data : data.filter(id => !projects[id]?.archived),
    buildTypes,
    pipelines,
    projects,
  }),
)

const getAllProjectsAndBuildTypesWithActiveProject = createSelector(
  prepareAllProjectAndBuildTypesToConvert,
  (state: State) => state.projectsSidebar.activeItem?.activeProjectId,
  (result, activeProjectId) =>
    activeProjectId != null && !result.data.includes(activeProjectId)
      ? {...result, data: [activeProjectId, ...result.data]}
      : result,
)

export const getDefaultAllProjectsTree: (arg0: State) => ProjectsTree | null | undefined =
  createSelector(
    getAllProjectsAndBuildTypesWithActiveProject,
    (state: State) => state.projectsSidebar.showArchivedProjects,
    ({ready, data, buildTypes, pipelines, projects}, showArchivedProjects) =>
      convertDataToTree({
        ready,
        data,
        buildTypes,
        pipelines,
        projects,
        group: 'all',
        showArchivedProjects,
      }),
  )

export const getProjectSubTree: (
  arg0: State,
  parentId: ProjectId,
) => ProjectsTree | null | undefined = createSelector(
  (state: State, parentId: ProjectId) => parentId,
  (state: State, parentId: ProjectId) => prepareAllProjectAndBuildTypesToConvert(state, parentId),
  (parentId, {ready, data, buildTypes, pipelines, projects}) =>
    convertDataToTree({
      ready,
      data,
      buildTypes,
      pipelines,
      projects,
      group: 'all',
      filter: {parentId},
    }),
)

export const getAllAncestorProjectsReady = (state: State) => {
  const projectId = state.projectsSidebar.activeItem?.activeProjectId
  const isFavoriteItemOpen = state.projectsSidebar.activeItem?.isFavoriteItemOpen
  const ancestorProjects = getProject(state, projectId)?.ancestorProjects?.project
  if (!projectId || isFavoriteItemOpen) {
    return true
  }
  if (!ancestorProjects) {
    return false
  }
  return (
    ancestorProjects.every(id => id === ROOT_PROJECT_ID || getProject(state, id) != null) ||
    getProjectsReady(state)
  )
}

export const getOpenProjectsTree: (state: State) => ProjectsTree | null | undefined =
  createSelector(
    (state: State) => state.projectsSidebar.allProjectsCollapsed,
    (state: State) => state.projectsSidebar.showArchivedProjects,
    (state: State) => state.projectsSidebar.activeItem?.activeProjectId,
    (state: State) => state.projectsSidebar.activeItem?.activeBuildTypeId,
    getAllAncestorProjectsReady,
    (state: State) =>
      getProjectsState(state, state.projectsSidebar.activeItem?.activeProjectId ?? undefined).data,
    getBuildTypesHash,
    getPipelinesHash,
    getProjectsHash,
    (
      collapsed,
      showArchivedProjects,
      projectId,
      buildTypeId,
      ready,
      data,
      buildTypes,
      pipelines,
      projects,
    ) =>
      projectId
        ? convertDataToTree({
            ready: ready && collapsed,
            data: [projectId, ...data],
            buildTypes,
            pipelines,
            projects,
            group: 'allOpen',
            showArchivedProjects,
            filter: {
              includedProjects: [projectId, ...data],
              includedBuildTypes: buildTypeId ? [buildTypeId] : undefined,
              removeSiblingBuildTypes: true,
            },
          })
        : null,
  )
const getAllProjectsTree: (state: State) => ProjectsTree = createSelector(
  getDefaultAllProjectsTree,
  getOpenProjectsTree,
  getAllProjectsExpandState,
  (state: State) => state.projectsSidebar.allProjectsCollapsed,
  (state: State) => state.projectsSidebar.showArchivedProjects,
  (defaultTree, openProjectsTree, expandState, allProjectsCollapsed, showArchivedProjects) =>
    upgradeTreeByExpandState({
      defaultTree: allProjectsCollapsed ? openProjectsTree : defaultTree,
      expandState,
      baseLevel: 1,
      shift: allProjectsCollapsed ? 1 : undefined,
      showArchivedProjects,
    }),
)
