export function getIsStarred({
  item,
  togglingOverview,
  overviewData,
  overviewProjectsHash,
}: {
  item: ProjectsTreeItem
  togglingOverview: TogglingOverview
  overviewData: Set<ProjectId>
  overviewProjectsHash: KeyValue<ProjectId, NormalizedProject>
}): boolean | null | undefined {
  if (item.isStarred != null) {
    return item.isStarred
  }

  if (item.serverId !== currentServerId) {
    return null
  }

  if (item.itemType === 'project') {
    const toggling = togglingOverview.project[item.id]
    return toggling ?? overviewData.has(item.id)
  } else if (item.itemType === 'buildType') {
    const toggling = togglingOverview.bt[item.id!]

    if (toggling != null) {
      return toggling
    } else if (overviewData.has(item.parentId)) {
      const buildTypes = overviewProjectsHash[item.parentId]?.buildTypes?.buildType
      return buildTypes ? buildTypes.includes(item.id!) : false
    } else {
      return false
    }
  }

  return null
}
type CreateSearchProjectsTreeParams = {
  searchQuery: string
  defaultTreeByServer: WritableMap<FederationServerId, ProjectsTree | null | undefined>
  togglingOverview: TogglingOverview
  overviewData: ReadonlyArray<ProjectId>
  overviewProjectsHash: KeyValue<ProjectId, NormalizedProject>
  federationServers?: ReadonlyArray<FederationServerId>
  parentId?: ProjectId
  includeRoot?: boolean
}
export function createSearchProjectsTree({
  searchQuery,
  defaultTreeByServer,
  togglingOverview,
  overviewData,
  overviewProjectsHash,
  federationServers = emptyArray,
  parentId = ROOT_PROJECT_ID,
  includeRoot = false,
}: CreateSearchProjectsTreeParams) {
  const servers = [currentServerId, ...federationServers]
  const result: WritableMap<FederationServerId, ProjectsTree> = new Map()
  const overviewDataSet = new Set(overviewData)
  const words: Array<string> = searchQuery.toLowerCase().split(' ').filter(Boolean)

  servers.forEach((serverId: FederationServerId) => {
    const defaultTree = defaultTreeByServer.get(serverId)
    let data: ProjectsTreeItem[] = []

    if (defaultTree?.data?.length) {
      const defaultTreeData = defaultTree.data
      const defaultTreeLength = defaultTreeData.length
      let index = 0

      if (words.length) {
        const worldStateMap = new Map()

        while (index < defaultTreeLength) {
          const treeItem = defaultTreeData[index]
          const {
            id: treeItemId,
            name: treeItemName,
            level: treeItemLevel,
            parentId: treeItemParentId,
            itemType: treeItemType,
          } = treeItem
          const possibleRootId = includeRoot ? treeItemId : treeItemParentId

          if (treeItemType === 'server') {
            data.push(treeItem)

            index++

            continue
          }

          if (possibleRootId == null || (possibleRootId !== parentId && treeItemParentId == null)) {
            index++
            continue
          }

          const nextIndex = index + 1
          const isItemTypeProject = treeItemType === 'project'
          const {level: nextTreeItemLevel} = defaultTreeData[nextIndex] ?? {}
          const lastParentMatchWorlds = worldStateMap.get(treeItemParentId) || words
          const remainingWorlds = getNoMatchingWords(
            treeItemName.toLowerCase(),
            lastParentMatchWorlds,
          )
          const isFullMatch = !remainingWorlds.length

          treeItem.isFullMatch = isFullMatch

          if (isItemTypeProject && isFullMatch) {
            do {
              const item = defaultTreeData[index]
              item.isFullMatch = true
              item.isStarred = getIsStarred({
                item,
                togglingOverview,
                overviewData: overviewDataSet,
                overviewProjectsHash,
              })
              data.push(item)

              index++
            } while (defaultTreeData[index]?.level > treeItemLevel)

            continue
          }

          data.push(treeItem)

          if (isItemTypeProject) {
            worldStateMap.set(treeItemId, remainingWorlds)
          }

          if (!isFullMatch && treeItemLevel >= nextTreeItemLevel) {
            let reverseIndex = data.length - 1

            while (
              data[reverseIndex] &&
              !data[reverseIndex]?.isFullMatch &&
              data[reverseIndex]?.level >= nextTreeItemLevel
            ) {
              data.pop()
              reverseIndex--
            }
          } else if (nextTreeItemLevel <= treeItemLevel || !nextTreeItemLevel) {
            let reverseIndex = data.length - 1

            while (data[reverseIndex] && !data[reverseIndex]?.isFullMatch) {
              data.pop()
              reverseIndex--
            }
          } else {
            treeItem.isStarred = getIsStarred({
              item: treeItem,
              togglingOverview,
              overviewData: overviewDataSet,
              overviewProjectsHash,
            })
          }

          if (isFullMatch) {
            treeItem.isStarred = getIsStarred({
              item: treeItem,
              togglingOverview,
              overviewData: overviewDataSet,
              overviewProjectsHash,
            })
          }

          index++
        }
      } else {
        data = [...defaultTree?.data]
      }
    }

    result.set(serverId, {
      data,
    })
  })

  return result
}

export const upgradeSearchProjectsTreeByExpandState = (
  federationServers: ReadonlyArray<FederationServerId>,
  searchProjectsTree: WritableMap<FederationServerId, ProjectsTree>,
  expandStates: KeyValue<ProjectId, ExpandState> | null | undefined,
  defaultExpandState = true,
) => {
  const expandStatesEntries = expandStates != null ? objectEntries(expandStates) : []
  const expandStateMap = new Map(expandStatesEntries)
  const expandStateMapSize = expandStateMap.size
  const servers = [currentServerId, ...federationServers]

  if (expandStateMapSize || !defaultExpandState) {
    const result: WritableMap<FederationServerId, ProjectsTree> = new Map()

    servers.forEach(server => {
      const projectsTree = searchProjectsTree.get(server)
      const data = []
      let index = 0
      let expandParentLevel = Infinity

      if (projectsTree?.data?.length) {
        while (index < projectsTree?.data.length) {
          let treeItem = projectsTree.data[index]
          const {itemType, level, id} = treeItem

          index++

          if (level > expandParentLevel) {
            continue
          } else {
            expandParentLevel = Infinity
          }

          if (treeItem && itemType === 'project') {
            const expandState = expandStateMap.get(id)?.expandState
            const isExpanded = expandState ? expandState === 'EXPANDED' : defaultExpandState

            treeItem = {...treeItem, expanded: isExpanded}

            if (!isExpanded && expandParentLevel === Infinity) {
              expandParentLevel = level
            }
          }

          data.push(treeItem)
        }
      }

      result.set(server, {
        data,
        _hash: undefined,
        get hash() {
          if (!this._hash) {
            this._hash = new Map(this.data.map(item => [item.key!, item]))
          }

          return this._hash
        },
      })
    })

    return result
  }

  return searchProjectsTree
}

export const mergeSearchProjectsTree = (
  treeByServer: WritableMap<FederationServerId, ProjectsTree>,
  federationServers: ReadonlyArray<FederationServerId>,
  federationServersData: KeyValue<FederationServerId, FederationServerData>,
): ProjectsTree => {
  let treeData: Array<ProjectsTreeItem> = []
  const servers = [currentServerId, ...federationServers]

  servers.forEach((serverId: FederationServerId) => {
    const tree = treeByServer.get(serverId)
    const serverData = federationServersData[serverId]

    if (tree?.data && (tree.data.length || (serverId !== baseUri && !serverData?.authorized))) {
      if (federationServers?.length) {
        if (serverId === baseUri) {
          treeData.push(getServerTitleItem(currentServerId))
        } else {
          const serverTitle = getServerTitleItem(
            serverId,
            Boolean(serverData?.authorized),
            serverData?.projects == null,
          )
          treeData.push(serverTitle)
        }
      }

      if (serverId === baseUri || Boolean(serverData?.authorized)) {
        treeData = treeData.concat(tree.data)
      }
    }
  })

  return {
    data: treeData,
  }
}
export function mergeProjectsForSidebar(
  favoriteProjects: ReadonlyArray<ProjectsTreeItem>,
  hasFavoriteProjects: boolean | null | undefined,
  allProjects: ReadonlyArray<ProjectsTreeItem> | null | undefined,
  allProjectsTitleItem: ProjectsTreeItem,
  needsFavourites: boolean,
  canShowProjectsToggle?: boolean,
  isFavoriteItemOpen?: boolean,
): ReadonlyArray<ProjectsTreeItem> {
  let items: Array<ProjectsTreeItem> = []

  if (needsFavourites) {
    items.push(favoriteBuildsLinkItem)
  }
  if (hasFavoriteProjects === true) {
    items.push(favoritesTitleItem)
    items.push(favoriteProjectsLinkItem)
    items = items.concat(favoriteProjects)
  }

  if (allProjects?.length || canShowProjectsToggle) {
    items.push(allProjectsTitleItem)
  }

  if (
    allProjects?.length &&
    ((allProjectsTitleItem.expanded === false && !isFavoriteItemOpen) ||
      allProjectsTitleItem.expanded === true)
  ) {
    items = items.concat(allProjects)
  }

  return items.length ? items : emptyArray
}

export const matchSidebarItem =
  (activeItem: SidebarActiveItem | null | undefined) =>
  ({group: nodeGroup, itemType, id: nodeId}: ProjectsTreeItem): boolean => {
    if (activeItem == null) {
      return false
    }
    const {nodeType, id: activeItemId, group: activeItemGroup} = activeItem

    if (nodeType === 'bt' || nodeType === 'project' || nodeType === 'pipeline') {
      if (
        nodeGroup !== activeItemGroup &&
        nodeGroup !== 'all' &&
        nodeGroup !== 'search' &&
        nodeGroup !== 'allOpen'
      ) {
        return false
      }
    }

    switch (itemType) {
      case 'project':
        return nodeType === 'project' && activeItemId === nodeId

      case 'buildType':
        return nodeType === 'bt' && activeItemId === nodeId

      case 'pipeline':
        return nodeType === 'pipeline' && activeItemId === nodeId

      case 'template':
        return nodeType === 'template' && activeItemId === nodeId

      case 'link':
        return nodeType === 'link' && activeItemId === nodeId

      case 'action':
        return nodeType === 'all' && nodeId === toCustomSidebarItemId('all item')

      default:
        return false
    }
  }
